// ============================================================
// service-a/rawHttpClient.ts  (hand-rolled outbound client)
// ============================================================
import * as net from 'net';

/**
 * Fires a POST over a raw TCP socket, assembling the request line and
 * headers by hand. Node's `http`/`https` module (which OTel's auto-
 * instrumentation patches) is never touched, so this call is completely
 * invisible to instrumentation.
 */
export function rawHttpPost(
  host: string,
  port: number,
  path: string,
  body: Record<string, unknown>,
): Promise<string> {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload).toString(),
    };
    // headers is built entirely by hand here — nothing ever calls
    // propagation.inject(context.active(), headers), so no `traceparent`
    // is ever written onto the outgoing request.

    const headerBlock = Object.entries(headers)
      .map(([k, v]) => `${k}: ${v}`)
      .join('\r\n');
    const requestText = `POST ${path} HTTP/1.1\r\nHost: ${host}\r\n${headerBlock}\r\n\r\n${payload}`;

    const socket = net.connect(port, host, () => socket.write(requestText));
    let data = '';
    socket.on('data', (chunk) => (data += chunk.toString()));
    socket.on('end', () => resolve(data));
    socket.on('error', reject);
  });
}

